package com.freshmart.identity;
import com.freshmart.common.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.util.*;
@Service
public class AuthenticationService {
 private final com.freshmart.checkout.CheckoutService checkout;private final IdentityMapper mapper;private final PasswordHasher passwords;private final TokenCodec tokens;private final CsrfService csrf;private final PermissionRegistry permissions;private final Clock clock;private final long accessTtl,refreshTtl;private final String dummyHash;private final LoginThrottlePolicy loginThrottle;
 public AuthenticationService(com.freshmart.checkout.CheckoutService checkout,IdentityMapper mapper,PasswordHasher passwords,TokenCodec tokens,CsrfService csrf,PermissionRegistry permissions,Clock clock,LoginThrottlePolicy loginThrottle,@Value("${app.access-ttl-seconds:900}")long accessTtl,@Value("${app.refresh-ttl-seconds:604800}")long refreshTtl){this.checkout=checkout;this.mapper=mapper;this.passwords=passwords;this.tokens=tokens;this.csrf=csrf;this.permissions=permissions;this.clock=clock;this.loginThrottle=loginThrottle;this.accessTtl=accessTtl;this.refreshTtl=refreshTtl;if(accessTtl<1||accessTtl>900||refreshTtl<1||refreshTtl>604800)throw new IllegalStateException("Invalid session TTL");this.dummyHash=passwords.encode(tokens.randomToken());}
 @Transactional public Issued register(String phone,String password,String displayName){if(mapper.userByPhone(phone)!=null)throw ApiException.conflict("该手机号已注册");Instant now=clock.instant();UserRow user=new UserRow(UUID.randomUUID().toString(),phone,passwords.encode(password),displayName,"ACTIVE",false,0,now,now);try{mapper.insertUser(user);mapper.insertRole(user.userId(),"MEMBER");checkout.claimNewcomerCoupon(user.userId());audit(user.userId(),"auth.register",user.userId(),"会员注册");}catch(DuplicateKeyException e){throw ApiException.conflict("该手机号已注册");}return issue(user,null,null);}
 @Transactional(noRollbackFor=ApiException.class) public Issued login(String phone,String password){return login(phone,password,null);}
 @Transactional(noRollbackFor=ApiException.class) public Issued login(String phone,String password,String remoteAddress){
  var locked=loginThrottle.lock(phone,remoteAddress);
  UserRow found=mapper.userByPhone(phone);UserRow user=found==null?null:mapper.lockUser(found.userId());
  boolean valid=passwords.matches(password,user==null?dummyHash:user.passwordHash());
  if(!valid||user==null||!"ACTIVE".equals(user.status())){loginThrottle.failure(locked);throw ApiException.unauthorized();}
  loginThrottle.success(locked);audit(user.userId(),"auth.login",user.userId(),"登录成功");return issue(user,null,null);
 }
 @Transactional(noRollbackFor=ApiException.class) public Issued refresh(String refresh){if(refresh==null||refresh.length()>256)throw ApiException.unauthorized();SessionRow lookup=mapper.sessionByRefreshHash(TokenCodec.hash(refresh));if(lookup==null)throw ApiException.unauthorized();UserRow lockedUser=mapper.lockUser(lookup.userId());SessionRow old=mapper.lockSessionByRefreshHash(TokenCodec.hash(refresh));if(old==null)throw ApiException.unauthorized();if(!"ACTIVE".equals(old.status())){mapper.revokeFamily(old.familyId());audit(old.userId(),"auth.refresh.replay",old.sessionId(),"检测到旧刷新凭据重放，吊销会话族");throw ApiException.unauthorized();}if(!old.refreshExpiresAt().isAfter(clock.instant())){mapper.revokeFamily(old.familyId());throw ApiException.unauthorized();}UserRow user=lockedUser;if(user==null||!"ACTIVE".equals(user.status())){mapper.revokeFamily(old.familyId());throw ApiException.unauthorized();}mapper.rotate(old.sessionId(),clock.instant());audit(user.userId(),"auth.refresh",old.sessionId(),"刷新凭据轮换");return issue(user,old.familyId(),old.refreshExpiresAt());}
 @Transactional public CommandResult logout(String refresh){if(refresh==null||refresh.length()>256)throw ApiException.unauthorized();SessionRow lookup=mapper.sessionByRefreshHash(TokenCodec.hash(refresh));if(lookup==null)throw ApiException.unauthorized();mapper.lockUser(lookup.userId());SessionRow row=mapper.lockSessionByRefreshHash(TokenCodec.hash(refresh));if(row==null)throw ApiException.unauthorized();mapper.revokeFamily(row.familyId());audit(row.userId(),"auth.logout",row.sessionId(),"退出并吊销会话族");return new CommandResult(true,row.sessionId(),0,"会话已吊销");}
 @Transactional public CommandResult changePassword(RequestActor actor,String current,String replacement){UserRow user=mapper.lockUser(actor.userId());if(user==null||!passwords.matches(current,user.passwordHash()))throw ApiException.unauthorized();if(current.equals(replacement))throw ApiException.invalid("新密码不能与当前密码相同");mapper.changePassword(user.userId(),passwords.encode(replacement),clock.instant());mapper.revokeUser(user.userId());audit(user.userId(),"auth.password",user.userId(),"密码已修改，吊销全部会话");return new CommandResult(true,user.userId(),user.version()+1,"密码已修改，请重新登录");}
 public RequestActor authenticate(String access){TokenCodec.Claims claims=tokens.verify(access);SessionRow row=mapper.sessionByAccessHash(TokenCodec.hash(access));if(row==null||!"ACTIVE".equals(row.status())||!row.accessExpiresAt().isAfter(clock.instant())||!row.sessionId().equals(claims.sessionId())||!row.userId().equals(claims.userId()))throw ApiException.unauthorized();UserRow user=mapper.userById(row.userId());if(user==null||!"ACTIVE".equals(user.status()))throw ApiException.unauthorized();Set<String>roles=Set.copyOf(mapper.roles(user.userId()));return new RequestActor(user.userId(),roles,permissions.permissions(roles),row.sessionId());}
 public UserView user(String userId){UserRow row=mapper.userById(userId);if(row==null)throw ApiException.notFound();return view(row);}
 private UserView view(UserRow user){var roles=mapper.roles(user.userId());String phone=user.phone();String masked=phone.length()>=7?phone.substring(0,3)+"****"+phone.substring(phone.length()-4):"***";return new UserView(user.userId(),user.displayName(),masked,roles,user.status(),user.version(),permissions.permissions(roles).stream().sorted().toList(),user.mustChangePassword());}
 private Issued issue(UserRow user,String family,Instant absoluteRefreshExpiry){Instant now=clock.instant();Instant refreshExpires=absoluteRefreshExpiry==null?now.plusSeconds(refreshTtl):absoluteRefreshExpiry;long remaining=Duration.between(now,refreshExpires).getSeconds();if(remaining<1)throw ApiException.unauthorized();long effectiveAccessTtl=Math.min(accessTtl,remaining);Instant accessExpires=now.plusSeconds(effectiveAccessTtl);String id=UUID.randomUUID().toString();String access=tokens.access(user.userId(),id,accessExpires);String refresh=tokens.randomToken();mapper.insertSession(new SessionRow(id,family==null?UUID.randomUUID().toString():family,user.userId(),TokenCodec.hash(access),TokenCodec.hash(refresh),"ACTIVE",accessExpires,refreshExpires,now,null));CsrfService.Issued c=csrf.issue();return new Issued(new AuthSession(access,"Bearer",effectiveAccessTtl,view(user),c.token(),c.expiresAt().toString()),refresh,c.cookie(),remaining);}

 private void audit(String actorId,String operation,String resourceId,String reason){mapper.audit(new IdentityAuditRow(UUID.randomUUID().toString(),actorId,operation,resourceId,reason,TraceContext.id(),clock.instant()));}
 public record UserView(String userId,String displayName,String phoneMasked,List<String>roles,String status,long version,List<String>permissions,boolean mustChangePassword){}
 public record AuthSession(String accessToken,String tokenType,long expiresIn,UserView user,String csrfToken,String csrfExpiresAt){}
 public record Issued(AuthSession body,String refresh,String csrfCookie,long refreshMaxAgeSeconds){}
 public record CommandResult(boolean accepted,String resourceId,long version,String message){}
}
